import type { ICanvas, Mirror } from '@posthog/rrweb-snapshot';
import type {
  blockClass,
  canvasManagerMutationCallback,
  canvasMutationCallback,
  canvasMutationCommand,
  canvasMutationWithType,
  IWindow,
  listenerHandler,
  CanvasArg,
  CanvasMasking,
  DataURLOptions,
} from '@posthog/rrweb-types';
import { isBlocked } from '../../../utils';
import { CanvasContext } from '@posthog/rrweb-types';
import { computeFrameMaskRegions, SKIP_FRAME } from './canvas-mask';
import initCanvas2DMutationObserver from './2d';
import initCanvasContextObserver from './canvas';
import initCanvasWebGLMutationObserver from './webgl';
import ImageBitmapDataURLWorker from '../../workers/image-bitmap-data-url-worker?worker&inline';
import type { ImageBitmapDataURLRequestWorker } from '../../workers/image-bitmap-data-url-worker';

export type RafStamps = { latestId: number; invokeId: number | null };

type pendingCanvasMutationsMap = Map<
  HTMLCanvasElement,
  canvasMutationWithType[]
>;

// lower bound for resolutionScale, so a misconfiguration can't capture at a degenerate
// resolution. matches the floor the PostHog SDK applies before passing the option in.
const MIN_CANVAS_RESOLUTION_SCALE = 0.1;

// Each path below turns canvas capture off for the whole session, so it must say why:
// otherwise the user sees an empty canvas in playback and no canvas events at all.
const CSP_BLOB_HINT =
  'A page CSP that omits blob: from worker-src or script-src blocks it';

function warnCanvasCapture(message: string, ...details: unknown[]): void {
  console.warn(`[replay] canvas capture: ${message}`, ...details);
}

export class CanvasManager {
  private pendingCanvasMutations: pendingCanvasMutationsMap = new Map();
  private rafStamps: RafStamps = { latestId: 0, invokeId: null };
  private mirror: Mirror;

  private mutationCb: canvasMutationCallback;
  private resetObservers?: listenerHandler;
  private frozen = false;
  private locked = false;
  private rafIdTimestamp: number | null = null;
  private rafIdFlush: number | null = null;
  private refCount = 0;
  private torndown = false;
  private resetFrameDedup: (() => void) | null = null;

  // Node ids are reused across full snapshots, so the encode worker's dedup
  // map would otherwise keep suppressing an idle canvas forever — leaving the
  // new snapshot's epoch without any frame to repaint that canvas from after
  // a seek. Called after each full snapshot so every canvas re-emits one frame.
  public onFullSnapshot(): void {
    this.resetFrameDedup?.();
  }

  // Shared by the main document and every iframe/shadow-root observer, so reference-count
  // teardown: a single root cleaning up must not unpatch getContext / stop the FPS loop globally.
  public acquire(): void {
    this.refCount += 1;
  }

  public reset(): void {
    if (this.refCount > 0) {
      this.refCount -= 1;
    }
    if (this.refCount > 0) {
      return;
    }
    this.teardown();
  }

  private teardown() {
    if (this.torndown) {
      return;
    }
    this.torndown = true;
    this.pendingCanvasMutations.clear();
    this.resetObservers && this.resetObservers();
    if (this.rafIdTimestamp !== null) {
      cancelAnimationFrame(this.rafIdTimestamp);
      this.rafIdTimestamp = null;
    }
    if (this.rafIdFlush !== null) {
      cancelAnimationFrame(this.rafIdFlush);
      this.rafIdFlush = null;
    }
  }

  public freeze(): void {
    this.frozen = true;
  }

  public unfreeze(): void {
    this.frozen = false;
  }

  public lock(): void {
    this.locked = true;
  }

  public unlock(): void {
    this.locked = false;
  }

  constructor(options: {
    recordCanvas: boolean;
    mutationCb: canvasMutationCallback;
    win: IWindow;
    blockClass: blockClass;
    blockSelector: string | null;
    mirror: Mirror;
    sampling?: 'all' | number;
    dataURLOptions: DataURLOptions;
    // fraction of the canvas display size to capture frames at, clamped to
    // [MIN_CANVAS_RESOLUTION_SCALE, 1]; the frame is upscaled back to its display size on replay,
    // so playback dimensions/aspect are unchanged, just softer. invalid/unset defaults to 1
    // (full resolution).
    resolutionScale?: number;
    canvasMasking?: CanvasMasking;
  }) {
    const {
      sampling = 'all',
      win,
      blockClass,
      blockSelector,
      recordCanvas,
      dataURLOptions,
      resolutionScale,
      canvasMasking,
    } = options;
    this.mutationCb = options.mutationCb;
    this.mirror = options.mirror;

    if (recordCanvas && sampling === 'all')
      this.initCanvasMutationObserver(
        win,
        blockClass,
        blockSelector,
        dataURLOptions,
      );
    if (recordCanvas && typeof sampling === 'number')
      this.initCanvasFPSObserver(sampling, win, blockClass, blockSelector, {
        dataURLOptions,
        resolutionScale,
        canvasMasking,
      });
  }

  private processMutation: canvasManagerMutationCallback = (
    target,
    mutation,
  ) => {
    const newFrame =
      this.rafStamps.invokeId &&
      this.rafStamps.latestId !== this.rafStamps.invokeId;
    if (newFrame || !this.rafStamps.invokeId)
      this.rafStamps.invokeId = this.rafStamps.latestId;

    if (!this.pendingCanvasMutations.has(target)) {
      this.pendingCanvasMutations.set(target, []);
    }

    this.pendingCanvasMutations.get(target)!.push(mutation);
  };

  private initCanvasFPSObserver(
    fps: number,
    win: IWindow,
    blockClass: blockClass,
    blockSelector: string | null,
    options: {
      dataURLOptions: DataURLOptions;
      resolutionScale?: number;
      canvasMasking?: CanvasMasking;
    },
  ) {
    if (!('OffscreenCanvas' in win)) {
      warnCanvasCapture(
        'disabled because this browser does not support OffscreenCanvas',
      );
      return;
    }

    // fraction of the canvas display size to capture frames at, clamped to
    // [MIN_CANVAS_RESOLUTION_SCALE, 1]; invalid/unset means full resolution.
    const scale =
      typeof options.resolutionScale === 'number' &&
      Number.isFinite(options.resolutionScale)
        ? Math.min(
            1,
            Math.max(MIN_CANVAS_RESOLUTION_SCALE, options.resolutionScale),
          )
        : 1;

    const canvasContextReset = initCanvasContextObserver(
      win,
      blockClass,
      blockSelector,
      true,
    );
    const snapshotInProgressMap: Map<number, boolean> = new Map();

    // The inline worker is materialized by the bundler as a `blob:` object URL and loaded via
    // `importScripts(blobURL)` inside the worker. A strict page CSP (worker-src/script-src blob:),
    // an ad blocker, or a transient network hiccup can make that load fail — synchronously as a
    // thrown error here, or asynchronously as a worker error event. Either way, warn and disable
    // canvas snapshotting instead of letting an uncaught NetworkError escape and pollute error
    // tracking; the rest of session replay keeps working.
    let worker: ImageBitmapDataURLRequestWorker;
    try {
      worker = new ImageBitmapDataURLWorker() as ImageBitmapDataURLRequestWorker;
    } catch (error) {
      warnCanvasCapture(
        `disabled because the encode worker did not start. ${CSP_BLOB_HINT}`,
        error,
      );
      // this returns before resetObservers is assigned, so teardown has nothing to
      // call: undo the getContext patch here or it stays on the page forever,
      // forcing preserveDrawingBuffer while nothing is being captured
      canvasContextReset();
      return;
    }

    let workerErrored = false;
    worker.onerror = (error) => {
      workerErrored = true;
      warnCanvasCapture(
        `stopped because the encode worker failed. ${CSP_BLOB_HINT}`,
        error,
      );
      // stop the capture loop; nothing can be encoded without the worker.
      cancelAnimationFrame(rafId);
      worker.terminate?.();
      this.resetFrameDedup = null;
    };
    this.resetFrameDedup = () => {
      worker.postMessage({ resetFrameDedup: true });
    };
    worker.onmessage = (e) => {
      const { id } = e.data;
      snapshotInProgressMap.set(id, false);

      if (!('base64' in e.data)) return;

      const { base64, type, displayWidth, displayHeight } = e.data;
      // the encoded image may be downscaled; draw it stretched back to the canvas's display
      // size — carried through the worker with the frame, so playback keeps the original
      // dimensions and aspect ratio, just softer.
      const dw = displayWidth;
      const dh = displayHeight;
      this.mutationCb({
        id,
        type: CanvasContext['2D'],
        commands: [
          {
            property: 'clearRect', // wipe canvas
            args: [0, 0, dw, dh],
          },
          {
            property: 'drawImage', // draws (semi-transparent) image, stretched to display size
            args: [
              {
                rr_type: 'ImageBitmap',
                args: [
                  {
                    rr_type: 'Blob',
                    data: [{ rr_type: 'ArrayBuffer', base64 }],
                    type,
                  },
                ],
              } as CanvasArg,
              0,
              0,
              dw,
              dh,
            ],
          },
        ],
        displayWidth: dw,
        displayHeight: dh,
      });
    };

    let maskSkipWarned = false;
    let snapshotFailureWarned = false;
    const timeBetweenSnapshots = 1000 / fps;
    let lastSnapshotTime = 0;
    let rafId: number;

    const getCanvas = (): HTMLCanvasElement[] => {
      const matchedCanvas: HTMLCanvasElement[] = [];
      const searchCanvas = (haystack: ParentNode) => {
        try {
          haystack.querySelectorAll('canvas').forEach((canvas) => {
            if (!isBlocked(canvas, blockClass, blockSelector, true)) {
              matchedCanvas.push(canvas);
            }
          });
          haystack.querySelectorAll('*').forEach((elem) => {
            if (elem.shadowRoot) {
              searchCanvas(elem.shadowRoot);
            }
          });
        } catch {
          // Don't let traversal errors cancel the rAF loop.
        }
      };
      searchCanvas(win.document);
      return matchedCanvas;
    };

    const takeCanvasSnapshots = (timestamp: DOMHighResTimeStamp) => {
      // the worker failed to load (e.g. CSP blocked the blob script); stop capturing.
      if (workerErrored) {
        return;
      }
      if (lastSnapshotTime && timestamp - lastSnapshotTime < timeBetweenSnapshots) {
        rafId = requestAnimationFrame(takeCanvasSnapshots);
        return;
      }
      lastSnapshotTime = timestamp;

      getCanvas()
        .forEach(async (canvas: HTMLCanvasElement) => {
          const id = this.mirror.getId(canvas);
          // every canvas the mirror does not know yet shares id -1: one dedup key in the
          // encode worker, and a mutation the player cannot apply to any node
          if (id === -1) return;
          if (snapshotInProgressMap.get(id)) return;

          // The browser throws if the canvas is 0 in size
          // Uncaught (in promise) DOMException: Failed to execute 'createImageBitmap' on 'Window': The source image width is 0.
          // Assuming the same happens with height
          if (canvas.width === 0 || canvas.height === 0) return;

          snapshotInProgressMap.set(id, true);
          try {
            if (['webgl', 'webgl2'].includes((canvas as ICanvas).__context)) {
              // if the canvas hasn't been modified recently,
              // its contents won't be in memory and `createImageBitmap`
              // will return a transparent imageBitmap

              const context = canvas.getContext(
                (canvas as ICanvas).__context,
              ) as WebGLRenderingContext | WebGL2RenderingContext | null;
              // Snapshotting a lost context produces a transparent bitmap
              // that poisons the worker's fingerprint dedup map; skip it.
              if (context?.isContextLost?.()) {
                snapshotInProgressMap.set(id, false);
                return;
              }
              if (
                context?.getContextAttributes()?.preserveDrawingBuffer === false
              ) {
                // Hack to load canvas back into memory so `createImageBitmap` can grab it's contents.
                // Context: https://twitter.com/Juice10/status/1499775271758704643
                // Preferably we set `preserveDrawingBuffer` to true, but that's not always possible,
                // especially when canvas is loaded before rrweb.
                // This hack can wipe the background color of the canvas in the (unlikely) event that
                // the canvas background was changed but clear was not called directly afterwards.
                // Example of this hack having negative side effect: https://visgl.github.io/react-map-gl/examples/layers
                context.clear(context.COLOR_BUFFER_BIT);
              }
            }
            // createImageBitmap throws if resizing to 0
            // Fallback to intrinsic size if canvas has not yet rendered
            const displayWidth = canvas.clientWidth || canvas.width;
            const displayHeight = canvas.clientHeight || canvas.height;
            // capture at a (optionally downscaled) resolution; replay upscales it back to the
            // display size, so playback dimensions/aspect are unchanged, just softer.
            const captureWidth = Math.max(1, Math.round(displayWidth * scale));
            const captureHeight = Math.max(1, Math.round(displayHeight * scale));
            // computed before the await so regions and display dims describe
            // the same frame even if the canvas resizes mid-snapshot
            const maskRegions = computeFrameMaskRegions(
              options.canvasMasking,
              canvas,
              captureWidth,
              captureHeight,
              displayWidth,
              displayHeight,
            );
            if (maskRegions === SKIP_FRAME) {
              if (!maskSkipWarned) {
                maskSkipWarned = true;
                warnCanvasCapture(
                  'dropped a frame because the mask provider did not return valid regions. A provider that always fails records no canvas frames at all',
                );
              }
              snapshotInProgressMap.set(id, false);
              return;
            }
            const bitmap = await createImageBitmap(
              canvas,
              // only ask for a quality resampling filter when we're actually downscaling;
              // at full resolution this keeps capture identical to before.
              scale < 1
                ? {
                    resizeWidth: captureWidth,
                    resizeHeight: captureHeight,
                    resizeQuality: 'medium',
                  }
                : { resizeWidth: captureWidth, resizeHeight: captureHeight },
            );
            // pass the display size through with the frame so the worker's reply can draw it
            // back to the right dimensions — no per-id state retained on the main thread.
            worker.postMessage(
              {
                id,
                bitmap,
                width: captureWidth,
                height: captureHeight,
                displayWidth,
                displayHeight,
                dataURLOptions: options.dataURLOptions,
                maskRegions,
              },
              [bitmap],
            );
          } catch (error) {
            if (!snapshotFailureWarned) {
              snapshotFailureWarned = true;
              warnCanvasCapture(
                'dropped a frame because the snapshot failed. A canvas that fails every frame records no canvas frames at all',
                error,
              );
            }
            snapshotInProgressMap.set(id, false);
          }
        });
      rafId = requestAnimationFrame(takeCanvasSnapshots);
    };

    rafId = requestAnimationFrame(takeCanvasSnapshots);

    this.resetObservers = () => {
      canvasContextReset();
      cancelAnimationFrame(rafId);
      // a dedicated worker is not terminated by becoming unreachable; without
      // this, every recorder restart leaks a worker thread plus its
      // capture-resolution OffscreenCanvas
      worker.terminate?.();
      this.resetFrameDedup = null;
    };
  }

  private initCanvasMutationObserver(
    win: IWindow,
    blockClass: blockClass,
    blockSelector: string | null,
    dataURLOptions: DataURLOptions,
  ): void {
    this.startRAFTimestamping();
    this.startPendingCanvasMutationFlusher();

    const canvasContextReset = initCanvasContextObserver(
      win,
      blockClass,
      blockSelector,
      false,
    );
    const canvas2DReset = initCanvas2DMutationObserver(
      this.processMutation.bind(this),
      win,
      blockClass,
      blockSelector,
      dataURLOptions,
    );

    const canvasWebGL1and2Reset = initCanvasWebGLMutationObserver(
      this.processMutation.bind(this),
      win,
      blockClass,
      blockSelector,
      dataURLOptions,
    );

    this.resetObservers = () => {
      canvasContextReset();
      canvas2DReset();
      canvasWebGL1and2Reset();
    };
  }

  private startPendingCanvasMutationFlusher() {
    this.rafIdFlush = requestAnimationFrame(() =>
      this.flushPendingCanvasMutations(),
    );
  }

  private startRAFTimestamping() {
    const setLatestRAFTimestamp = (timestamp: DOMHighResTimeStamp) => {
      this.rafStamps.latestId = timestamp;
      this.rafIdTimestamp = requestAnimationFrame(setLatestRAFTimestamp);
    };
    this.rafIdTimestamp = requestAnimationFrame(setLatestRAFTimestamp);
  }

  flushPendingCanvasMutations(): void {
    this.pendingCanvasMutations.forEach(
      (_values: canvasMutationCommand[], canvas: HTMLCanvasElement) => {
        const id = this.mirror.getId(canvas);
        this.flushPendingCanvasMutationFor(canvas, id);
      },
    );
    this.rafIdFlush = requestAnimationFrame(() =>
      this.flushPendingCanvasMutations(),
    );
  }

  flushPendingCanvasMutationFor(canvas: HTMLCanvasElement, id: number): void {
    if (this.frozen || this.locked) {
      return;
    }

    const valuesWithType = this.pendingCanvasMutations.get(canvas);
    if (!valuesWithType || id === -1) return;

    const values = valuesWithType.map((value) => {
      const { type, ...rest } = value;
      return rest;
    });
    const { type } = valuesWithType[0];

    this.mutationCb({ id, type, commands: values });

    this.pendingCanvasMutations.delete(canvas);
  }
}
